import numpy as np
import pandas as pd


def _capped_inv_vol(inv, target, cap):
    n = len(inv)
    if n == 0 or target <= 0:
        return np.zeros(n, dtype=float)
    target = min(float(target), cap * n)
    inv = np.asarray(inv, dtype=float)
    inv = np.where(np.isfinite(inv) & (inv > 0), inv, 0.0)
    if inv.sum() <= 0:
        w = np.full(n, target / n, dtype=float)
        return np.minimum(w, cap)
    w = np.zeros(n, dtype=float)
    active = np.ones(n, dtype=bool)
    remaining = float(target)
    for _ in range(n + 2):
        idx = np.flatnonzero(active)
        if idx.size == 0:
            break
        s = inv[idx].sum()
        if s <= 0:
            w[idx] += remaining / idx.size
            remaining = 0.0
            break
        lam = remaining / s
        raw = lam * inv[idx]
        over = raw >= cap - 1e-15
        if not np.any(over):
            w[idx] = raw
            remaining = 0.0
            break
        over_idx = idx[over]
        w[over_idx] = cap
        active[over_idx] = False
        remaining -= cap * over_idx.size
        if remaining <= 1e-15:
            remaining = 0.0
            break
    if remaining > 1e-12:
        idx = np.flatnonzero(active & (w < cap - 1e-15))
        if idx.size:
            room = cap - w[idx]
            add = min(remaining, room.sum())
            if room.sum() > 0:
                w[idx] += add * room / room.sum()
    return np.minimum(w, cap)


