import pandas as pd


def _capped_inv_vol(inv, target, cap):
    n = len(inv)
    if n == 0 or target <= 0:
        return np.zeros(n, dtype=float)
    target = min(float(target), cap * n)
    inv = np.asarray(inv, dtype=float)
